:root {
  --ink: #162534;
  --muted: #617080;
  --card: #ffffff;
  --navy: #18354a;
  --line: #dce5e8;
  --soft-blue: #edf5f7;
  --blue: #3a92ad;
  --lime: #c9e85b;
  --lime-ink: #304318;
  --orange: #ffab48;
  --orange-ink: #6d3d00;
  --red: #df6d68;
}

.parcel-console {
  box-sizing: border-box;
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--card);
  color: var(--ink);
}

.console-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 15px 18px 13px;
  border-bottom: 1px solid var(--line);
}

.title-wrap h1 {
  margin: 3px 0 0;
  font-size: 22px;
  font-weight: 750;
  line-height: 1;
  letter-spacing: -0.6px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.8px;
}

.status-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--lime);
  color: var(--lime-ink);
  font-size: 12px;
  font-weight: 750;
}

.status-dot,
.key-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--lime-ink);
}

.route-grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 11px;
  padding: 13px 18px;
}

.map-card,
.package-card {
  box-sizing: border-box;
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.map-card {
  margin: 0;
  padding: 11px;
  background: var(--soft-blue);
}

.map-top,
.package-top,
.console-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.route-label,
.label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.55px;
  text-transform: uppercase;
}

.route-code {
  color: var(--blue);
  font-size: 12px;
}

.route-line {
  display: flex;
  align-items: center;
  margin: 15px 2px 10px;
}

.node {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border: 2px solid var(--blue);
  border-radius: 50%;
  background: var(--card);
  color: var(--blue);
  font-size: 10px;
  font-style: normal;
  font-weight: 800;
}

.node.mid {
  border-color: var(--orange);
  color: var(--orange-ink);
}

.node.end {
  border-color: var(--navy);
  background: var(--navy);
  color: var(--card);
}

.track {
  height: 2px;
  flex: 1;
  background: var(--orange);
}

.track.active {
  background: var(--navy);
}

.route-note,
.meter-caption {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.25;
}

.package-card {
  padding: 11px;
}

.tag {
  padding: 3px 6px;
  border-radius: 5px;
  background: var(--orange);
  color: var(--orange-ink);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.55px;
}

.package-id {
  font-size: 12px;
  letter-spacing: 0.3px;
}

.info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin: 13px 0 11px;
}

.info-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
}

.value {
  font-size: 16px;
  line-height: 1;
}

.meter {
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--line);
}

.meter-fill {
  display: block;
  width: 62%;
  height: 100%;
  border-radius: inherit;
  background: var(--blue);
}

.meter-caption {
  margin-top: 6px;
}

.console-footer {
  gap: 12px;
  padding: 11px 18px;
  background: var(--navy);
}

.key {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0;
  color: var(--card);
  font-size: 11px;
  font-weight: 600;
}

.key-dot {
  flex: 0 0 auto;
  background: var(--lime);
}

.unlock {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 11px;
  border: 0;
  border-radius: 8px;
  background: var(--lime);
  color: var(--lime-ink);
  font-size: 12px;
  font-weight: 800;
}

.unlock span {
  font-size: 17px;
  line-height: 0.7;
}
